import { WebChartTypes } from "@arcgis/charts-spec";
import { getChartOrSeriesType } from "../misc";
import { fetchCommonStrings } from "../t9n/common";
export function getChartIcon(chart) {
    const chartType = getChartOrSeriesType(chart.series);
    let chartIcon = "graph-bar";
    switch (chartType) {
        case WebChartTypes.LineSeries: {
            chartIcon = "graph-time-series";
            break;
        }
        case WebChartTypes.PieSeries: {
            chartIcon = "pie-chart";
            break;
        }
        case WebChartTypes.HistogramSeries: {
            chartIcon = "graph-histogram";
            break;
        }
        case WebChartTypes.ScatterSeries: {
            chartIcon = "graph-scatter-plot";
            break;
        }
        case WebChartTypes.BoxPlotSeries: {
            chartIcon = "box-chart";
            break;
        }
        case WebChartTypes.BarSeries:
        default: {
            break;
        }
    }
    return chartIcon;
}
/**
 * Gets the chart type text based on the provided chart type.
 * @param chartType
 * @param el
 * @category Private
 */
export async function getChartText(chartType) {
    const commonStrings = await fetchCommonStrings();
    let chartText = "";
    switch (chartType) {
        case WebChartTypes.HistogramSeries: {
            chartText = commonStrings.chartType.histogram;
            break;
        }
        case WebChartTypes.ScatterSeries: {
            chartText = commonStrings.chartType.scatterPlot;
            break;
        }
        case WebChartTypes.BarSeries: {
            chartText = commonStrings.chartType.barChart;
            break;
        }
        case WebChartTypes.LineSeries: {
            chartText = commonStrings.chartType.lineChart;
            break;
        }
        case WebChartTypes.PieSeries: {
            chartText = commonStrings.chartType.pieChart;
            break;
        }
        case WebChartTypes.BoxPlotSeries: {
            chartText = commonStrings.chartType.boxPlot;
            break;
        }
        default: {
            break;
        }
    }
    return chartText;
}
