import { defaultBarLineFromFieldsName, defaultBarLineFromFieldsValue, defaultPieFromFieldsName, defaultPieFromFieldsValue, RESTFieldType, RESTStatisticType, WebChartTypes, WebChartVersionStatus, } from "@arcgis/charts-spec";
import { WebChartJSONSchemas } from "@arcgis/charts-spec/dist/json-schema";
import Ajv from "ajv";
import { getBoxPlotYList, isGaugeByFeature } from "../../data";
import { defaultBoxPlotCategory, queryDefaults } from "../../defaults";
import { ErrorKeywords } from "../../errors/interfaces";
import { fetchLayerFieldsInfo, getFieldFromName, isNumericField } from "../../layer";
import { getLayerFromQueryObject, getMainLayer } from "../../layer/utils";
import { formatMessage } from "../../localization";
