import { getChartSubType, getChartVersionInfo, getSeriesReference, getSplitByField, isAbsoluteTruthWhereClause, } from "../utils";
import { ConfigErrorKeywords, ConfigWarningKeywords } from "./interfaces";
/**
 * Extracts schema name from the schema `$ref` path
 * For e.g.:
 *   - "#/definitions/WebChartInlineDataSource" => "WebChartInlineDataSource"
 *   - "#/definitions/WebChartBarChartSeries" => "WebChartBarChartSeries"
 * @param schemaRefPath
 */
function extractSchemaNameFromRefPath(schemaRefPath) {
    const schemaStartIndex = schemaRefPath.lastIndexOf("/");
    return schemaStartIndex !== -1 ? schemaRefPath.slice(schemaStartIndex + 1) : schemaRefPath;
}
async function customizeValidationErrors(errors) {
    const errorStrings = await fetchErrorsStrings();
    return errors.map((error) => {
        let customizedError = error;
        const dataPath = error.dataPath.startsWith(".") ? error.dataPath.substring(1) : error.dataPath;
        switch (error.keyword) {
            case ConfigErrorKeywords.Required:
                customizedError = {
                    ...error,
                    message: formatMessage(errorStrings.requiredProperty, {
                        dataPath,
                        missingProperty: error.params.missingProperty,
                    }),
                };
                break;
            case ConfigErrorKeywords.MinLength:
                // TODO: Figure out if it uses LimitParams or Comparison Params
                customizedError = {
                    ...error,
                    message: formatMessage(errorStrings.minLength, {
                        dataPath,
                        limit: error.params.limit.toString(),
                    }),
                };
                break;
            case ConfigErrorKeywords.MinItems:
                customizedError = {
                    ...error,
                    message: formatMessage(errorStrings.minItems, {
                        dataPath,
                        limit: error.params.limit.toString(),
                    }),
                };
                break;
            case ConfigErrorKeywords.MaxItems:
                customizedError = {
                    ...error,
                    message: formatMessage(errorStrings.maxItems, {
                        dataPath,
                        limit: error.params.limit.toString(),
                    }),
                };
                break;
            case ConfigErrorKeywords.Pattern:
                if (error.params.pattern === "\\w+") {
                    customizedError = {
                        ...error,
                        message: formatMessage(errorStrings.whiteSpacePattern, {
                            dataPath,
                        }),
                        params: {},
                    };
                }
                break;
            case ConfigErrorKeywords.AdditionalProperties:
                customizedError = {
                    ...error,
                    message: formatMessage(errorStrings.additionalProperty, {
                        dataPath,
                        additionalProperty: error.params.additionalProperty,
                    }),
                };
                break;
            case ConfigErrorKeywords.Enum:
                customizedError = {
                    ...error,
                    message: formatMessage(errorStrings.enumValues, {
                        dataPath,
                        allowedValues: error.params.allowedValues.join(", "),
                    }),
                };
                break;
            case ConfigErrorKeywords.AnyOf: {
                let params = [];
                if (error.schemaPath === "#/properties/legend/anyOf") {
                    params = WebChartJSONSchemas.definitions.WebChart.properties.legend.anyOf.map((schemaRef) => extractSchemaNameFromRefPath(schemaRef.$ref));
                }
                customizedError = {
                    ...error,
                    params,
                    message: formatMessage(errorStrings.anyOfValues, {
                        dataPath,
                        schemaOptions: params.join(", "),
                    }),
                };
                break;
            }
            default:
                break;
        }
        return customizedError;
    });
}
/**
 * By default, the JSON schema created by ac-spec is suitable for WebChart validation.
 * If we want to validate any other object, an appropriate schema can be generated via this function.
 * @param schema
 * @param schemaKey
 */
function createStartingSchema(schema, schemaKey) {
    return { ...schema, $ref: `#/definitions/${schemaKey}` };
}
async function findLayerLoadError(queryObject) {
    let error;
    const errorStrings = await fetchErrorsStrings();
    const layer = getLayerFromQueryObject(queryObject);
    try {
        await layer.load();
    }
    catch (e) {
        const url = layer?.url ?? "";
        const portalItemId = getMainLayer(layer)?.portalItem?.id ?? "";
        error = {
            keyword: ErrorKeywords.LayerLoadFailure,
            message: formatMessage(errorStrings.layerLoadFailure, {
                url,
                portalItemId,
            }),
            params: { url, portalItemId },
        };
    }
    return error;
}
/**
 * Generates AJV Validator function.
 * Returns a closure having a reference to the validator function.
 * Refer to [Getting Started with Ajv](https://ajv.js.org/#getting-started) for more details.
 * @param input The input chart config
 * @param seriesType The type of series config
 */
function generateValidatorFunction() {
    const validatorInstance = new Ajv({ allErrors: true });
    return async (input, seriesType) => {
        let chartJSONSchema = WebChartJSONSchemas; // By default, the schema is ready for WebChart validation.
        // TODO: Replace with switch cases at some point...
        if (seriesType === WebChartTypes.GaugeSeries) {
            chartJSONSchema = createStartingSchema(WebChartJSONSchemas, "WebGaugeChart"); // Modifying the schema for WebGaugeChart validation.
        }
        if (input && !("iLayer" in input)) {
            chartJSONSchema = createStartingSchema(WebChartJSONSchemas, "WebMapWebChart"); // Modifying the schema for WebMapWebChart validation.
        }
        const validatorFunction = validatorInstance.compile(chartJSONSchema);
        validatorFunction(input); // asserting as boolean because our validation is not async
        let errors = [];
        if (validatorFunction.errors !== null && validatorFunction.errors !== undefined) {
            errors = await customizeValidationErrors(validatorFunction.errors);
        }
        return errors;
    };
}
/**
 * Finds all the errors in the `WebChart` config at once. If the first error is on say, line 10, then the error
 * reported on line 20 may not be accurate until the error on line 10 is fixed first.
 */
const findSchemaErrors = generateValidatorFunction();
/**
 * Check whether there exists a `StatisticDefinition` in any series' `Query` where non-count aggregation is applied to a non-numeric field
 * @param props.seriesConfigs The series config list
 * @param props.queryObject The query object
 * @param props.allowUsingObjectIdStat Whether to allow using the object id field as a statistic field
 */
async function findNumericAggregationWarnings(props) {
    const { seriesConfigs, queryObject, allowUsingObjectIdStat } = props;
    const warnings = [];
    const layerFields = await fetchLayerFieldsInfo(queryObject);
    const errorStrings = await fetchErrorsStrings();
    for (let i = 0; i < seriesConfigs.length; i += 1) {
        const outStatistics = seriesConfigs[i].query?.outStatistics;
        if (outStatistics !== undefined) {
            for (let j = 0; j < outStatistics.length; j += 1) {
                const statDefinition = outStatistics[j];
                const field = getFieldFromName(statDefinition.onStatisticField, layerFields);
                if (field) {
                    // the field is allowed if it's a numeric field or if it's an object id field and the flag allowing it is set
                    const fieldTypeAllowed = (field.type === RESTFieldType.OID && allowUsingObjectIdStat) || isNumericField(field);
                    if (!fieldTypeAllowed && statDefinition.statisticType !== RESTStatisticType.Count) {
                        const dataPath = `series[${i}].query.outStatistics[${j}]`;
                        warnings.push({
                            keyword: ConfigWarningKeywords.NonNumericAggregation,
                            message: formatMessage(errorStrings.nonNumericAggregation, {
                                dataPath,
                            }),
                            dataPath,
                            params: {
                                fieldName: statDefinition.onStatisticField,
                                fieldType: field.type,
                                aggregationRequested: statDefinition.statisticType,
                            },
                        });
                    }
                }
            }
        }
    }
    return warnings;
}
/**
 * Verifies that the chart series are unique. Sets a message to display if not.
 * @param chartConfig
 */
async function findDuplicateSeriesIDWarnings(chartConfig) {
    const warnings = [];
    const errorStrings = await fetchErrorsStrings();
    if (chartConfig !== undefined && chartConfig.series.length > 1) {
        // Creating a Set which will contain the list of the series id without duplicates
        const listIds = new Set();
        let previousCount = 0;
        chartConfig.series.forEach((series, seriesIndex) => {
            listIds.add(series.id);
            // if no new id has been added to the set, it means its a duplicate
            if (listIds.size === previousCount) {
                const dataPath = `series[${seriesIndex}].id`;
                warnings.push({
                    keyword: ConfigWarningKeywords.DuplicateSeriesID,
                    message: formatMessage(errorStrings.duplicateSeriesID, {
                        dataPath,
                        seriesID: series.id,
                        seriesName: series.name,
                    }),
                    dataPath,
                    params: {
                        seriesId: series.id,
                        seriesName: series.name,
                    },
                });
            }
            else {
                previousCount += 1;
            }
        });
    }
    return warnings;
}
/**
 * Retrieves all the required field names from the chart config.
 * @param chartConfig The chart config
 * @returns the list of required field names
 */
function getRequiredFieldNamesFromChartConfig(chartConfig) {
    const fieldNameList = new Set();
    const seriesReference = getSeriesReference(chartConfig);
    if (seriesReference) {
        const chartType = getChartOrSeriesType(chartConfig.series);
        const chartSubType = getChartSubType(chartConfig.series);
        /**
         * 1. process the x field name
         */
        const isStatisticGauge = chartType === WebChartTypes.GaugeSeries && !isGaugeByFeature(chartConfig);
        const chartHasNoRequiredXField = isStatisticGauge ||
            chartSubType === ChartSubType.PieFromFields ||
            chartSubType === ChartSubType.BarAndLineFromFields ||
            chartSubType === ChartSubType.BoxPlotMonoField ||
            chartSubType === ChartSubType.BoxPlotMultiFields ||
            chartSubType === ChartSubType.BoxPlotMonoFieldAndSplitBy ||
            chartSubType === ChartSubType.BoxPlotMultiFieldsAndSplitBy;
        // only get add the x field to the fieldNameList if the chart requires the x field to be a layer field
        if (!chartHasNoRequiredXField) {
            fieldNameList.add(seriesReference.x);
        }
        /**
         * 2. process the y field names
         */
        // scatterplot and non-aggregated bar/line/pie charts require the y field to be a layer field
        const yFieldIsLayerField = chartType === WebChartTypes.ScatterSeries ||
            chartSubType === ChartSubType.BarAndLineNoAggregation ||
            chartSubType === ChartSubType.BarAndLineSplitByNoAggregation ||
            chartSubType === ChartSubType.PieNoAggregation;
        // list of technical fields or placeholders to remove from the field name list to avoid creating false positives
        const fieldsToExclude = [
            defaultBoxPlotCategory,
            defaultPieFromFieldsName,
            defaultBarLineFromFieldsName,
            defaultPieFromFieldsValue,
            defaultBarLineFromFieldsValue,
            queryDefaults.outStatistics.outStatisticFieldName ?? "",
        ];
        // get the list of y field names from all the series
        let yList = [];
        if (chartType === WebChartTypes.BoxPlotSeries) {
            yList = getBoxPlotYList({
                showMean: chartConfig.showMean,
                seriesConfig: chartConfig.series,
            });
        }
        else {
            yList = chartConfig.series
                .map((series) => ("y" in series ? series.y : undefined))
                .filter((y) => y !== undefined)
                .flat();
        }
        // if a chart requires the y fields to be layer fields, those y fields should be added to the  `fieldNameList`;
        // otherwise, they need to be added to the `fieldsToExclude` list, which eventually used to clean up entries from the `fieldNameList`
        if (yFieldIsLayerField) {
            yList.forEach((y) => fieldNameList.add(y));
        }
        else {
            fieldsToExclude.push(...yList);
        }
        /**
         * 3. process the fields from the series queries
         */
        chartConfig.series.forEach((series) => {
            const { query } = series;
            if (query) {
                // splitBy field name
                if (!isAbsoluteTruthWhereClause(query.where)) {
                    fieldNameList.add(getSplitByField(query.where));
                }
                // field names under groupByFieldsForStatistics[]
                if (query.groupByFieldsForStatistics) {
                    query.groupByFieldsForStatistics.forEach((field) => fieldNameList.add(field));
                }
                // fields under outStatistics[].onStatisticField
                if (query.outStatistics) {
                    query.outStatistics.forEach((stat) => fieldNameList.add(stat.onStatisticField));
                }
            }
        });
        /**
         * 4. process the fields from the axe for gauge chart
         */
        if (chartType === WebChartTypes.GaugeSeries && chartConfig.axes?.[0] !== undefined) {
            const gaugeAxis = chartConfig.axes?.[0];
            if (gaugeAxis && "minimumFromField" in gaugeAxis && typeof gaugeAxis.minimumFromField === "string") {
                fieldNameList.add(gaugeAxis.minimumFromField);
            }
            if (gaugeAxis && "maximumFromField" in gaugeAxis && typeof gaugeAxis.maximumFromField === "string") {
                fieldNameList.add(gaugeAxis.maximumFromField);
            }
        }
        // TODO: process the fields from the orderByFields under orderOptions
        /**
         * 5. Finally we remove the fields to exclude from the field name list before returning it
         */
        fieldsToExclude.forEach((field) => {
            fieldNameList.delete(field);
        });
    }
    // return the list of field names that is not empty
    return Array.from(fieldNameList.values()).filter((field) => !isEmptyStringField(field));
}
/**
 * Finds the fields that are defined in the chart config but not found in the layer.
 * @param chartConfig The chart config
 * @param queryObject The query object
 * @returns
 */
async function findMissingFieldsErrors(chartConfig, queryObject) {
    let missingFieldsErrors;
    const errorStrings = await fetchErrorsStrings();
    const layerFields = await fetchLayerFieldsInfo(queryObject);
    const fieldNames = getRequiredFieldNamesFromChartConfig(chartConfig);
    // get all the missing field names
    const missingFieldList = fieldNames.filter((fieldName) => !getFieldFromName(fieldName, layerFields));
    // if there are missing fields, create an error object
    if (missingFieldList.length > 0) {
        const fieldNames = missingFieldList.join(", ");
        missingFieldsErrors = {
            keyword: ErrorKeywords.LayerFieldsNotFound,
            message: formatMessage(errorStrings.layerFieldsNotFound, { fieldNames }),
            params: fieldNames,
        };
    }
    return missingFieldsErrors;
}
/**
 * Look for issues of level 'warning' in the chart config.
 * @param props.input The input config
 * @param props.queryObject The query object
 * @param props.allowUsingObjectIdStat Whether to allow using the object id field as a statistic field
 */
async function findWarnings(props) {
    const { input, queryObject, allowUsingObjectIdStat } = props;
    let warnings = [];
    if (queryObject !== undefined) {
        const numericAggregationWarnings = await findNumericAggregationWarnings({
            seriesConfigs: input.series,
            queryObject,
            allowUsingObjectIdStat,
        });
        warnings = warnings.concat(numericAggregationWarnings);
    }
    warnings = warnings.concat(await findDuplicateSeriesIDWarnings(input));
    return warnings;
}
async function findCustomErrors(queryObject, chartConfig) {
    let errors = [];
    // Error: the layer can't load
    if (queryObject !== undefined) {
        const layerLoadError = await findLayerLoadError(queryObject);
        if (layerLoadError !== undefined) {
            errors = errors.concat(layerLoadError);
        }
        else if (chartConfig !== undefined) {
            const missingFieldsErrors = await findMissingFieldsErrors(chartConfig, queryObject);
            if (missingFieldsErrors !== undefined) {
                errors = errors.concat(missingFieldsErrors);
            }
        }
    }
    return errors;
}
/**
 * Validates the `WebChart` config by checking for  and displays `Errors` and `Warnings`.
 * - `Errors` are violations in the config w.r.t the JSON schema.
 * - `Warnings` are undesired combinations in the config which don't violate the JSON schema but should still be blocked.
 * @param props.input The input config
 * @param props.queryObject The query object
 * @param props.allowUsingObjectIdStat Whether to allow using the object id field as a statistic field
 */
export async function validateWebChart(props) {
    const { input, queryObject, allowUsingObjectIdStat } = props;
    // TODO: CT: add a function for unsupported chart type and call it here?
    let status;
    if (getChartVersionInfo(input?.version).versionStatus === WebChartVersionStatus.Newer) {
        // skip validating the web chart if it's newer
        status = { valid: true, schemaErrors: [], customErrors: [], warnings: [] };
    }
    else {
        const schemaErrors = await findSchemaErrors(input);
        let warnings = [];
        let customErrors = [];
        if (input !== undefined && schemaErrors.length === 0) {
            customErrors = await findCustomErrors(queryObject, input);
            if (customErrors.length === 0) {
                warnings = await findWarnings({ input, queryObject, allowUsingObjectIdStat });
            }
        }
        status = {
            valid: schemaErrors.length === 0 && warnings.length === 0 && customErrors.length === 0,
            schemaErrors,
            customErrors,
            warnings,
        };
    }
    return status;
}
/**
 * Checks whether the config is "partial", meaning it has been initialized for a given chart type
 * but has not been provided the minimum required prop(s) yet.
 * @param config The config to analyze
 */
export function isPartialConfig(config) {
    const chartType = getChartOrSeriesType(config?.series);
    let isPartial = false;
    switch (chartType) {
        case WebChartTypes.ComboLineAndBarSeries:
        case WebChartTypes.HistogramSeries: {
            // Radar Chart, Line Chart or Histogram missing "x" field is a partial config
            isPartial = (config?.series?.[0]?.x?.trim()?.length ?? 0) === 0;
            break;
        }
        case WebChartTypes.ScatterSeries: {
            // Scatter Plot missing "x" field or "y" field is a partial config
            const scatterSeries = config?.series;
            isPartial = (scatterSeries?.[0]?.x?.length ?? 0) === 0 || (scatterSeries?.[0]?.y?.length ?? 0) === 0;
            break;
        }
        case WebChartTypes.PieSeries: {
            const pieSeries = config?.series;
            // Check if pie is in "Fields" mode or "Category" mode
            if (getChartSubType(pieSeries) === ChartSubType.PieFromFields) {
                // If Pie From Fields, Pie Chart with no numeric fields is a partial config
                isPartial = (pieSeries?.[0]?.query?.outStatistics?.length ?? 0) === 0;
            }
            else {
                // If Pie From Category, Pie Chart missing "x" field is a partial config
                isPartial = (pieSeries?.[0]?.x?.length ?? 0) === 0 || pieSeries?.[0]?.x === defaultPieFromFieldsName;
            }
            break;
        }
        case WebChartTypes.BoxPlotSeries: {
            const boxPlotSeries = config?.series;
            // Box Plot missing "y" field is a partial config
            isPartial = [boxPlotSeries?.[0]?.y].flat().length === 0 || boxPlotSeries?.[0]?.y === "";
            break;
        }
        case WebChartTypes.RadarSeries:
        case WebChartTypes.BarSeries:
        case WebChartTypes.LineSeries: {
            const allSeries = config?.series;
            // Check if the chart is in "Fields" mode or "Category" mode
            if (getChartSubType(allSeries) === ChartSubType.BarAndLineFromFields) {
                // In "Fields" mode, bar/line/radar chart with no numeric fields is a partial config
                isPartial = (allSeries?.[0]?.query?.outStatistics?.length ?? 0) === 0;
            }
            else {
                // In "Category" mode, bar/line/radar chart missing "x" field is a partial config
                isPartial = (allSeries?.[0]?.x?.trim()?.length ?? 0) === 0;
            }
            break;
        }
        default:
            break;
    }
    return isPartial;
}
