import { RESTStatisticType, } from "@arcgis/charts-spec";
/**
 * Indicates whether the input object is an instance of `FeatureLayerView`.
 * @param queryObject
 */
export function isFeatureLayerView(queryObject) {
    return queryObject !== undefined && "layer" in queryObject;
}
/**
 * Indicates whether the input object is an instance of `FeatureLayer`.
 * @param queryObject
 */
export function isFeatureLayer(queryObject) {
    return queryObject !== undefined && "type" in queryObject && queryObject.type === "feature";
}
/**
 * Indicates whether the input object is an instance of `SubtypeGroupLayer`.
 * @param queryObject
 */
export function isSubtypeGroupLayer(queryObject) {
    return queryObject !== undefined && "type" in queryObject && queryObject.type === "subtype-group";
}
// TODO: Need to revisit.  When the queryObject is undefined, runtime error will occur when it tries to get the layer.
/**
 * Indicates whether the input object is an instance of `SubtypeSublayer`.
 * @param queryObject
 */
export function isSubtypeSublayer(queryObject) {
    return queryObject !== undefined && "type" in queryObject && queryObject.type === "subtype-sublayer";
}
export function getMainLayer(layer) {
    return isSubtypeSublayer(layer) ? layer.parent : layer;
}
/**
 * Indicates whether a feature layer supports queries with a `distance` parameter
 * @param layer The layer to test
 * @returns A boolean
 */
export function doesLayerSupportQueryWithDistance(layer) {
    return (layer.capabilities?.query?.supportsDistance ||
        getMainLayer(layer).sourceJSON?.advancedQueryCapabilities?.supportsQueryWithDistance === true);
}
/**
 * Indicates whether the layer supports the cacheHint parameter for the queryBins operation
 * @param queryObject The layer or feature layer view
 */
export function doesLayerSupportsCacheHintForQueryBins(queryObject) {
    return getMainLayer(getLayerFromQueryObject(queryObject))?.sourceJSON?.advancedQueryCapabilities.supportedOperationsWithCacheHint.includes("queryBins");
}
/**
 * Indicates whether the layer supports the query bins operation for scatterplot:
 * - supports queryBins
 * - supports the type `fixedIntervalBin`
 * - statistics: supports MAX and COUNT
 * @param queryObject The layer or feature layer view
 */
export function doesLayerSupportsQueryBinsForScatterplot(queryObject) {
    let supports = false;
    const mainLayer = getMainLayer(getLayerFromQueryObject(queryObject));
    const layerInfo = mainLayer.sourceJSON;
    if (layerInfo) {
        const supportsFixedIntervalBin = layerInfo.queryBinsCapabilities?.supportsFixedIntervalBin;
        // the query for scatterplot requires the MAX and COUNT to be supported
        const supportedStatisticTypes = layerInfo.queryBinsCapabilities?.supportedStatisticTypes;
        const supportsStats = [RESTStatisticType.Maximum, RESTStatisticType.Count].every((statType) => supportedStatisticTypes?.includes(statType.toUpperCase()) ||
            supportedStatisticTypes?.includes(statType.toLowerCase()));
        supports = supportsFixedIntervalBin && supportsStats;
    }
    return supports;
}
/**
 * Returns a feature layer from a QueryObject instance.
 * It will use the QueryObject itself if it's a Feature Layer, or the `layer` property from it if it's a Feature Layer View.
 * @param queryObject
 */
export function getLayerFromLayerOrLayerView(layerOrLayerView) {
    let layer;
    if (isFeatureLayerView(layerOrLayerView)) {
        layer = layerOrLayerView.layer;
    }
    else {
        layer = layerOrLayerView;
    }
    return layer;
}
/**
 * Returns a feature layer from a QueryObject instance.
 * It will use the QueryObject itself if it's a Feature Layer, or the `layer` property from it if it's a Feature Layer View.
 * @param queryObject
 */
export function getLayerFromQueryObject(queryObject) {
    let layer;
    if (isFeatureLayerView(queryObject)) {
        layer = queryObject.layer;
    }
    else {
        layer = queryObject;
    }
    return layer;
}
/**
 * Computes a feature layer capabilities regarding its spatial aggregation statistics.
 * Only considers the 'EnvelopeAggregate' for now.
 * @param layer The layer instance
 * @returns A sum up of the capabilities
 */
export function getLayerSpatialAggregationStatisticsCapabilities(layer) {
    let compatibleWithEnvelopeAggregate = false;
    const supportedSpatialAggregationStatisticsJSON = getMainLayer(layer).sourceJSON?.advancedQueryCapabilities?.supportedSpatialAggregationStatistics ?? [];
    const supportedSpatialAggregationStatistics = layer.capabilities?.query.supportedSpatialAggregationStatistics ?? {};
    compatibleWithEnvelopeAggregate =
        supportedSpatialAggregationStatisticsJSON.includes("EnvelopeAggregate") ||
            ("envelope" in supportedSpatialAggregationStatistics &&
                supportedSpatialAggregationStatistics.envelope !== undefined &&
                supportedSpatialAggregationStatistics.envelope !== null);
    return compatibleWithEnvelopeAggregate;
}
/**
 * Adds a iLayer to a WebMapWebChart.
 * If the `queryObject` prop is provided an `iLayer` is added to the config.
 * @param props.chartConfig The chart config with no iLayer
 * @param props.queryObject The layer or feature layer view instance. Its information are **not** used to create the iLayer.
 * @returns The update chart config with a `iLayer` property
 */
export function addILayer(props) {
    const { chartConfig, queryObject } = props;
    let iLayer;
    const layer = getLayerFromQueryObject(queryObject);
    if (layer) {
        // defining the basic mandatory properties for a iLayer
        iLayer = {
            id: layer.id,
            layerType: "ArcGISFeatureLayer",
        };
        if (layer.url) {
            iLayer.url = layer.url;
        }
    }
    return { ...chartConfig, iLayer };
}
