import { RESTSymbolType, WebChartTypes, WebChartVersionStatus } from "@arcgis/charts-spec";
import { chartConfigVersions, firstWebMapVersion, unrecognizedVersion } from "../interfaces";
import { ChartSubType } from "../../misc/interfaces";
import { escapeSQLString, getChartOrSeriesType, normalizeString } from "../../misc";
import { defaultBoxPlotCategory } from "../../defaults";
// TODO: use other library like the npm semver to handle the validation and comparing of chart versions
/**
 * Compare two version numbers.
 *
 * @param versionA a valid chart version to compare to
 * @param versionB a valid chart version to compare with
 * @returns 1 if versionA > versionB
 *         -1 if versionA < versionB
 *          0 if versionA === versionB
 */
function compareVersions(versionA, versionB) {
    let compareResult = 0; // versionA === versionB
    if (versionA !== versionB) {
        // TODO: check for valid version numbers?
        const partsNumberA = versionA.split(".");
        const partsNumberB = versionB.split(".");
        for (let i = 0; i < partsNumberA.length; i += 1) {
            const valueA = Number.parseInt(partsNumberA[i], 10);
            const valueB = Number.parseInt(partsNumberB[i], 10);
            // if A is larger than B
            if (valueA > valueB || Number.isNaN(valueB)) {
                compareResult = 1;
                break;
            }
            if (valueA < valueB) {
                compareResult = -1;
                break;
            }
        }
    }
    return compareResult;
}
// TODO: use other library like the npm semver to handle the validation and comparing of chart versions
/**
 * Check if a chart version is valid.
 *
 * A version is considered as valid when it is defined, has three components separated by a dot and all are valid numbers.
 * @param chartVersion The version to check.
 * @returns
 */
function isValidChartVersionFormat(chartVersion) {
    const regex = /^([1-9]\d*|0)(\.(([1-9]\d*)|0)){2}$/u;
    return chartVersion !== undefined ? regex.test(chartVersion) : false;
}
/**
 * Retrieve and construct chart version information based on the input version and the currently supported ArcGIS Chart versions
 * defined in `chartConfigVersions`.  Returned information includes:
 *
 * - versionStatus: whether the input chart version is the same | older | newer | unrecognized, comparing with the current chart version,
 * which is defined in `WebChartCurrentVersion`.  An unrecognized version is one that is neither undefined nor conformed to the
 * sematic versioning spec, that is `Major.Minor.Patch`
 * - versions: an array of versions that will be used in the `appConversion()`.
 *  + For any version that is not recognized, versions will be set to `unrecognizedVersion`;
 *  + If the input version is the same or newer, versions will be the input version;
 *  + Otherwise, versions will be a list of versions that is older and closer to the input version, plus all the supported versions
 * that are newer than the input version.
 *
 * Note: The input chart version needs to conform to the format defined by sematic versioning spec; otherwise it will be treated as unrecognized.
 *
 * @param configVersion The input config version.
 */
export function getChartVersionInfo(configVersion) {
    let versionStatus = WebChartVersionStatus.Same;
    let versions = [];
    // TODO: try to resolve user input error? for example 1.0 ==> 1.0.0.  This can be handled in `isValidChartVersion()` if needed
    const validVersionFormat = isValidChartVersionFormat(configVersion);
    if (validVersionFormat && configVersion !== undefined) {
        // filter and sort the `chartConfigVersions` to prevent human errors
        chartConfigVersions.sort(compareVersions);
        // compare the input chart version against the latest one from the list of supported version to see if it's newer
        const compareResult = compareVersions(configVersion, chartConfigVersions[chartConfigVersions.length - 1]);
        if (compareResult === 1) {
            versionStatus = WebChartVersionStatus.Newer;
        }
        else if (compareResult === -1) {
            versionStatus = WebChartVersionStatus.Older;
        }
        // if version is the same or newer...
        if (versionStatus === WebChartVersionStatus.Newer || versionStatus === WebChartVersionStatus.Same) {
            versions.push(configVersion);
        }
        else {
            // if the version is older, try to determine if the version is greater than or equal the second last one in the list
            // the goal is to find the closet version number so that the conversion process will pick it up from there and skip the much older ones.
            for (let i = chartConfigVersions.length - 2; i >= 0; i -= 1) {
                if (compareVersions(configVersion, chartConfigVersions[i]) >= 0) {
                    versions = chartConfigVersions.slice(i, chartConfigVersions.length);
                    break;
                }
            }
            // This should not happen but for some reason, if the version is valid but not found in the supported list,
            // we assign the first web map version so that the conversion process can start from there
            if (versions.length === 0) {
                versions.push(firstWebMapVersion);
            }
        }
    }
    else {
        versionStatus = WebChartVersionStatus.Unrecognized;
        // for now, with invalid (or unrecognized) chart version, we will trigger the conversion to try to convert everything
        versions.push(unrecognizedVersion);
    }
    return { versionStatus, versions };
}
/**
 * Get the series to use as a reference for the chart. That's the one containing important common information like the query,
 * the split-by field, etc.
 * For box plot we need to handle the specific case of the mean line series.
 * @param chartConfig The chart config
 */
export function getSeriesReference(chartConfig) {
    const { series: seriesConfig } = chartConfig;
    const showMean = "showMean" in chartConfig ? chartConfig.showMean : false;
    // in mean lines mode for box plot (showMean: true), the first series doesn't always contain the expected information.
    // In that case we look for the first line series instead
    let seriesReference = showMean === true ? seriesConfig.find((s) => s.type === WebChartTypes.LineSeries) : seriesConfig[0];
    seriesReference ??= seriesConfig[0];
    return seriesReference;
}
/**
 * Find the expected symbol type for a guide given the start and end values.
 * @param guide The guide to analyze
 */
export function findExpectedGuideSymbol(start, end) {
    const startValue = start !== null ? start.toString() : null;
    const endValue = end !== null && end !== undefined ? end.toString() : null;
    return endValue !== null && endValue !== startValue ? RESTSymbolType.SFS : RESTSymbolType.SLS;
}
/**
 * Extract the field name from equality-where clauses like `field = 'some_value'`.
 * This field is actually stored in each series where clause.
 * TODO: do we want to enforce the test by seeing if the extracted field is part of the feature layer list of fields?
 * E.g.:
 * "field = 'some_value'" => "field"
 * "field > 'some_value'" => ""
 * @param where the where clause to extract the field from
 * @param normalize whether to normalize the extracted field; by default it's true
 */
export function getSplitByField(where, normalize) {
    let field = "";
    if (where !== undefined && where.includes("=")) {
        field = normalize !== false ? normalizeString({ value: where.split("=")[0] }) : where.split("=")[0].trim();
    }
    return field;
}
/**
 * Extract the value from equality-where clauses like `field = 'some_value'`.
 * Optionally normalize or escape single quotes in the returned value according to the `normalize` param value.
 * If normalize is undefined then normalize the returned value.
 * For string value, if normalize is set to false and escape is set to false or undefined, the value is returned as is.
 * @param props.where the where clause to extract the value from
 * @param props.normalize whether to normalize the extracted value; default is true
 * @param props.keepSurroundingQuotes whether to keep the surrounding quotes; default is false
 * @param props.escape whether to escape the extracted value; default is false
 */
export function getSplitByValue(props) {
    const { where, normalize, keepSurroundingQuotes, escape } = props;
    let value = "";
    if (where !== undefined && where.includes("=")) {
        // To preserve any equal sign in the value from the where clause, we need to join the rest of the array;
        // Also, using slice() to retain the original values including spaces, quotes, etc.
        // see issue https://devtopia.esri.com/WebGIS/arcgis-charts/issues/8087, and
        // PR https://devtopia.esri.com/WebGIS/arcgis-charts/pull/8138 for more details
        value = where.split("=").slice(1).join("=").trim();
        // if the value:
        // - is "null" (and not "'null'")
        // - is a number
        // => we don't transform it to a string
        if (value === "null") {
            value = null;
        }
        else if (value.trim() !== "" && !Number.isNaN(Number(value))) {
            value = Number(value);
        }
        else if (normalize === false) {
            // if the value:
            // - is a string
            // - normalize is set to false
            // - escape is set to false or undefine
            // => we return the value as is
            if (escape === true) {
                value = escapeSQLString(value);
            }
        }
        else {
            value = normalizeString({ value, keepSurroundingQuotes, escape });
        }
    }
    return value;
}
/**
 * Detects a where clause being always true, as in 1=1, 2 = 2, 'some_value'='some_value'
 * @param where
 */
export function isAbsoluteTruthWhereClause(where) {
    let alwaysTrue = false;
    if (where === undefined || where === "") {
        alwaysTrue = true;
    }
    else if (where.includes("=")) {
        const fieldName = getSplitByField(where, false);
        const value = getSplitByValue({ where, normalize: false });
        alwaysTrue = fieldName === `${value}`;
    }
    return alwaysTrue;
}
/**
 * Normalizes a where clause, by escaping the "'" character and other special characters if needed.
 * Ex:
 *   - where = "field = 5" => returns "field = 5"
 *   - where = "field = 'value'" => returns "field = 'value'"
 *   - where = "field = 'va'lue'" => returns "field = 'va''lue'"
 * @param props.where the where clause to normalize
 * @param props.normalize whether to normalize the where clause
 * @param props.escape whether to escape the where clause
 */
export function normalizeWhereClause(props) {
    const { where, normalize, escape } = props;
    const normalizeReturnedValue = normalize === undefined ? true : normalize;
    const splitByField = getSplitByField(where);
    const splitByValue = getSplitByValue({
        where,
        normalize: normalizeReturnedValue,
        keepSurroundingQuotes: true,
        escape,
    });
    let normalizedWhere = where;
    if (splitByField !== "" && splitByValue !== "") {
        normalizedWhere = `${splitByField}=${splitByValue}`;
    }
    return normalizedWhere;
}
/**
 * Gets the query type for the pie.
 * @param series the pie series
 */
function getPieChartChartSubType(series) {
    let chartSubType = ChartSubType.PieFromCategory;
    if (series[0].query?.outStatistics === undefined) {
        chartSubType = ChartSubType.PieNoAggregation;
    }
    else if (series[0].query?.groupByFieldsForStatistics === undefined) {
        chartSubType = ChartSubType.PieFromFields;
    }
    return chartSubType;
}
/**
 * Gets the query type for bar/line chart.
 * @param series the bar/line series
 */
function getBarLineChartSubType(series) {
    let chartSubType = ChartSubType.BarAndLineMonoField;
    const whereClause = series[0].query?.where;
    if (series[0].query?.groupByFieldsForStatistics === undefined && (series[0].query?.outStatistics ?? []).length > 0) {
        chartSubType = ChartSubType.BarAndLineFromFields;
    }
    else if (whereClause === undefined && series[0].query?.outStatistics === undefined) {
        chartSubType = ChartSubType.BarAndLineNoAggregation;
    }
    else if (!isAbsoluteTruthWhereClause(whereClause)) {
        chartSubType =
            series[0].query?.outStatistics === undefined
                ? ChartSubType.BarAndLineSplitByNoAggregation
                : ChartSubType.BarAndLineSplitBy;
    }
    else if (series.length > 1) {
        chartSubType = ChartSubType.BarAndLineMultiFields;
    }
    return chartSubType;
}
/**
 * Gets the query type for box plot chart.
 * @param seriesConfig the box plot series config
 */
export function getBoxPlotChartSubType(seriesConfig) {
    let chartSubType = ChartSubType.BoxPlotMonoField;
    const monoSeries = seriesConfig.length === 1;
    // if the series array contains a mix of box plot and line series, it means we are in mean lines mode and
    // we need to pick the first LINE series as the reference
    const seriesReference = seriesConfig.find((s) => s.type === WebChartTypes.LineSeries) ?? seriesConfig[0];
    const { x } = seriesReference;
    const y = "y" in seriesReference ? seriesReference.y : "";
    const whereClause = seriesReference.query?.where;
    switch (x) {
        case defaultBoxPlotCategory:
            // if an array of fields is provided
            if (typeof y === "object" && y.length > 1) {
                if (!isAbsoluteTruthWhereClause(whereClause)) {
                    chartSubType = ChartSubType.BoxPlotMultiFieldsAndSplitBy;
                }
                else if (monoSeries) {
                    chartSubType = ChartSubType.BoxPlotMultiFields;
                }
            }
            else if (monoSeries) {
                chartSubType = ChartSubType.BoxPlotMonoField;
            }
            else if (!isAbsoluteTruthWhereClause(whereClause)) {
                chartSubType = ChartSubType.BoxPlotMonoFieldAndSplitBy;
            }
            break;
        default:
            if (monoSeries) {
                chartSubType = ChartSubType.BoxPlotMonoFieldAndCategory;
            }
            else if (!isAbsoluteTruthWhereClause(whereClause)) {
                chartSubType = ChartSubType.BoxPlotMonoFieldAndCategoryAndSplitBy;
            }
            else {
                chartSubType = ChartSubType.BoxPlotMultiFieldsAndCategory;
            }
            break;
    }
    return chartSubType;
}
/**
 * Returns the type of query we're dealing with. The actual values are:
 * a. Simple (0): single query using an aggregation
 * b. NoAggregation (1): single or multiple queries not using any aggregation
 * c. SplitByFieldValues (2): multiple queries using a specific field as a split-by
 * d. SplitByNumericalFields (3): multiple queries using multiple numerical fields as a split-by
 * e. PieFromFields (4): single query using more than one statistics fields
 * f. For Box-plot: one of the 7 combinations.
 * @param series The config series. Refrain from using `[firstSeries]` in place of `config.series` to avoid incorrect result,
 * especially for box-plot, bar and line charts.
 */
export function getChartSubType(series) {
    let chartSubType = ChartSubType.NonSpecific;
    if (series?.[0] !== undefined) {
        const chartType = getChartOrSeriesType(series);
        switch (chartType) {
            case WebChartTypes.PieSeries:
                chartSubType = getPieChartChartSubType(series);
                break;
            case WebChartTypes.RadarSeries:
            case WebChartTypes.BarSeries:
            case WebChartTypes.LineSeries:
            case WebChartTypes.ComboLineAndBarSeries:
                chartSubType = getBarLineChartSubType(series);
                break;
            case WebChartTypes.BoxPlotSeries:
                chartSubType = getBoxPlotChartSubType(series);
                break;
            default:
                break;
        }
    }
    return chartSubType;
}
/**
 * Indicates whether the bar or line series is configured to use time binning.
 * @param props.seriesConfig The series configuration
 * @param props.xAxisValueFormatType The x-axis value format type
 * @param props.setTimeBinningInfoWhenNotProvided Boolean indicating whether we want to set the time binning info when not provided
 */
export function isSeriesUsingTimeBinning(props) {
    const { seriesConfig, xAxisValueFormatType, setTimeBinningInfoWhenNotProvided } = props;
    let decision = false;
    // Only for:
    // - bar or line series
    // - using a date axis
    // - and when `binTemporalData` is not set to false
    if ((seriesConfig.type === WebChartTypes.LineSeries || seriesConfig.type === WebChartTypes.BarSeries) &&
        seriesConfig.binTemporalData !== false &&
        xAxisValueFormatType === WebChartTypes.DateAxisFormat) {
        const chartSubType = getChartSubType([seriesConfig]);
        // Only if an aggregation is set
        if (chartSubType !== ChartSubType.BarAndLineNoAggregation &&
            chartSubType !== ChartSubType.BarAndLineSplitByNoAggregation) {
            const { timeIntervalUnits, timeIntervalSize } = seriesConfig;
            // Only if the interval unit and size are provided, or if `setTimeBinningInfoWhenNotProvided` is set to true
            decision =
                setTimeBinningInfoWhenNotProvided === true ||
                    (timeIntervalSize !== undefined && timeIntervalSize > 0 && timeIntervalUnits !== undefined);
        }
    }
    return decision;
}
